def solve():
    a, b = map(int, input().split())

    # If already equal
    if a == b:
        return 0

    # Find GCD of a and b
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    g = gcd(a, b)

    # If the GCD is not equal to both a and b, then we can only reduce to a common divisor
    # The pieces can only be made equal if they can both be reduced to the same value
    # This common value must be a common divisor of both a and b
    # So we want to reduce both a and b to some common value d that divides both
    # The only possible d is the GCD of a and b

    # Check if both a and b can be reduced to g
    # For a piece of mass m, we can only reduce it by dividing by 2, 3, or 5
    # So we need to check if we can reduce a to g and b to g using only divisions by 2, 3, 5

    def can_reduce(n, target):
        # Reduce n to target by repeatedly dividing by 2, 3, or 5
        while n != target:
            if n < target:
                return False
            if n % 2 == 0 and n // 2 == target:
                n //= 2
            elif n % 3 == 0 and n // 3 == target:
                n //= 3
            elif n % 5 == 0 and n // 5 == target:
                n //= 5
            else:
                return False
        return True

    # The only possible common value is the GCD
    if not can_reduce(a, g) or not can_reduce(b, g):
        return -1

    # Count operations to reduce a to g
    def count_operations(n, target):
        ops = 0
        while n != target:
            if n < target:
                return -1
            if n % 2 == 0 and n // 2 == target:
                n //= 2
                ops += 1
            elif n % 3 == 0 and n // 3 == target:
                n //= 3
                ops += 1
            elif n % 5 == 0 and n // 5 == target:
                n //= 5
                ops += 1
            else:
                return -1
        return ops

    ops_a = count_operations(a, g)
    ops_b = count_operations(b, g)

    return ops_a + ops_b

print(solve())
